const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Great Lakes geometry (bounding box)
  const greatLakes = ee.Geometry.Rectangle([-92, 41, -75, 47]);

  // 2. Define dates
  const date1 = '2021-02-20';
  const date2 = '2021-03-03';

  // 3. Function to detect ice using NDIS (Normalized Difference Ice Index)
  function calculateIceCoverage(date, label) {
    let col = ee.ImageCollection('COPERNICUS/S2')
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .filterBounds(greatLakes)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

    const size = col.size().getInfo();
    console.log(`${label} Images Found: ${size}`);

    if (size === 0) {
      return null;
    }

    // Cloud mask using QA60
    function maskClouds(image) {
      const qa = image.select('QA60');
      const cloudBitMask = 1 << 10;
      const cirrusBitMask = 1 << 11;
      const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      return image.updateMask(mask);
    }

    col = col.map(maskClouds);

    // Median composite
    const img = col.median();

    // Calculate NDIS: (B3-B11) / (B3+B11) where B3=Green, B11=SWIR
    const ndis = img.normalizedDifference(['B3', 'B11']).rename('NDIS');

    // Ice typically has NDIS > 0.4
    const iceMap = ndis.gte(0.4);

    // Calculate valid pixels and ice coverage
    const pixelCount = iceMap.reduceRegion(
      {reducer: ee.Reducer.count(), geometry: greatLakes, scale: 500, maxPixels: 1e9}
    ).get('NDIS').getInfo();

    const icePixels = iceMap.reduceRegion(
      {reducer: ee.Reducer.sum(), geometry: greatLakes, scale: 500, maxPixels: 1e9}
    ).get('NDIS').getInfo();

    console.log(`${label} - Valid Pixels: ${pixelCount}, Ice Pixels: ${icePixels}`);

    if (!pixelCount || pixelCount === 0) {
      return null;
    }

    const iceCoverage = (icePixels / pixelCount) * 100;
    console.log(`${label} - Ice Coverage: ${iceCoverage.toFixed(2)}%`);

    return iceCoverage;
  }

  // 4. Calculate ice coverage for both dates
  const coverage1 = calculateIceCoverage(date1, 'Feb 20, 2021');
  const coverage2 = calculateIceCoverage(date2, 'Mar 03, 2021');

  // 5. Validate and determine answer
  if (coverage1 === null) {
    console.log('No valid data for Feb 20, 2021');
    console.log('C1');
    return;
  }

  if (coverage2 === null) {
    console.log('No valid data for Mar 03, 2021');
    console.log('C1');
    return;
  }

  if (coverage1 === 0 && coverage2 === 0) {
    console.log('C2');
    return;
  }

  const decrease = coverage1 - coverage2;
  console.log(`Ice Coverage Change: ${decrease.toFixed(2)}%`);

  if (decrease > 0) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
